import itertools

def is_too_close(p1, p2):
    for v1, v2 in zip(p1, p2):
        if abs(v1 - v2) > 1:
            return False
    return True

n = 3
perms = list(itertools.permutations(range(1, n + 1)))
adj = {i: [] for i in range(len(perms))}
for i in range(len(perms)):
    for j in range(i + 1, len(perms)):
        if is_too_close(perms[i], perms[j]):
            adj[i].append(j)
            adj[j].append(i)

def get_max_independent_set(nodes, adj):
    # Since the number of nodes is small, we can use brute force
    max_set = 0
    for i in range(1 << len(nodes)):
        subset = []
        for j in range(len(nodes)):
            if (i >> j) & 1:
                subset.append(nodes[j])

        is_independent = True
        for u in subset:
            for v in subset:
                if v in adj[u]:
                    is_independent = False
                    break
            if not is_independent:
                break

        if is_independent:
            max_set = max(max_set, len(subset))
    return max_set

visited = [False] * len(perms)
total_max_independent_set = 0
for i in range(len(perms)):
    if not visited[i]:
        component = []
        stack = [i]
        visited[i] = True
        while stack:
            u = stack.pop()
            component.append(u)
            for v in adj[u]:
                if not visited[v]:
                    visited[v] = True
                    stack.append(v)
        total_max_independent_set += get_max_independent_set(component, adj)

print(f"n=3, total_max_independent_set={total_max_independent_set}")

import itertools

def count_close_perms(n):
    perms = list(itertools.permutations(range(1, n + 1)))
    r = perms[0]
    count = 0
    for s in perms:
        is_close = True
        for i in range(n):
            if abs(s[i] - r[i]) > 1:
                is_close = False
                break
        if is_close:
            count += 1
    return count

for n in range(2, 6):
    print(f"n={n}, count={count_close_perms(n)}")

